window.PRACTICE_SHEET_DATA["cell_cycle_ncert"] = [{"subject": "Biology", "chapter": "Cell cycle and cell division", "q": "The sequence of events by which cells duplicate their genome, synthesize the other components of cell which eventually distribute into two daughter cells is called -", "opts": ["Quiescent stage", "Generation time", "Cell cycle", "Kinetochore"], "ans": 2, "mark": "Imp", "exp": "Cell cycle = sequence of events: genome duplication, synthesis of other components, distribution into two daughter cells."}, {"subject": "Biology", "chapter": "Cell cycle and cell division", "q": "DNA replication occurs in -", "opts": ["S phase", "G1 phase", "G2 phase", "M phase"], "ans": 0, "mark": "Imp", "exp": "DNA replication occurs in the S (synthesis) phase of interphase."}, {"subject": "Biology", "chapter": "Cell cycle and cell division", "q": "The phase between the two successive M phase is called as -", "opts": ["Metaphase", "Anaphase", "Prophase", "Interphase"], "ans": 3, "mark": "Imp", "exp": "Interphase lies between two successive M phases."}, {"subject": "Biology", "chapter": "Cell cycle and cell division", "q": "A biosynthetic phase where cell organelle duplicate itself is -", "opts": ["Interphase", "Anaphase", "Prophase", "Telophase"], "ans": 0, "mark": "Imp", "exp": "Interphase is the biosynthetic phase where the cell grows and organelles duplicate."}, {"subject": "Biology", "chapter": "Cell cycle and cell division", "q": "Yeast can progress through the cell cycle in about -", "opts": ["90 sec", "90 min", "90 hrs", "90 yrs"], "ans": 1, "mark": "Imp", "exp": "Yeast completes a cell cycle in about 90 minutes."}, {"subject": "Biology", "chapter": "Cell cycle and cell division", "q": "________ represents the most active stage of the cell cycle.", "opts": ["Metaphase", "Anaphase", "Telophase", "Interphase"], "ans": 3, "mark": "Imp", "exp": "Interphase is the most metabolically active stage of the cell cycle."}, {"subject": "Biology", "chapter": "Cell cycle and cell division", "q": "Interphase is called the resting phase because -", "opts": ["It is the most active phase of the cell cycle", "It does not involve any activity related to cell division", "It does not prepare cell for cell division", "It is the phase where cell rests before entering into mitosis"], "ans": 1, "mark": "Imp", "exp": "'Resting phase' is a misnomer: no division happens, but the cell is very active preparing for division."}, {"subject": "Biology", "chapter": "Cell cycle and cell division", "q": "_____ phase synthesizes enzymes required during S phase.", "opts": ["G2", "M", "S", "G1"], "ans": 3, "mark": "Imp", "exp": "G1 synthesises the enzymes/proteins needed for DNA replication in S phase."}, {"subject": "Biology", "chapter": "Cell cycle and cell division", "q": "Non-dividing cells enter the -", "opts": ["G2 phase", "M phase", "G0 phase", "S phase"], "ans": 2, "mark": "Imp", "exp": "Cells that stop dividing exit G1 and enter the G0 (quiescent) phase."}, {"subject": "Biology", "chapter": "Cell cycle and cell division", "q": "The cells which enter _________ phase start differentiating into specific types of cell.", "opts": ["G1", "G2", "S", "G0"], "ans": 3, "mark": "Imp", "exp": "Cells in G0 leave the cycle and differentiate into specific cell types."}, {"subject": "Biology", "chapter": "Cell cycle and cell division", "q": "If the initial amount of DNA is 8 C, then after S phase the amount of DNA would be -", "opts": ["4 C", "8 C", "64 C", "16 C"], "ans": 3, "mark": "Imp", "exp": "DNA doubles in S phase, so 8C becomes 16C."}, {"subject": "Biology", "chapter": "Cell cycle and cell division", "q": "The number of chromosomes in G1 phase is 36, the number of chromosomes in S phase is -", "opts": ["36", "18", "22", "37"], "ans": 0, "mark": "Imp", "exp": "S phase doubles DNA but chromosome number stays 36."}, {"subject": "Biology", "chapter": "Cell cycle and cell division", "q": "A phase of the cell cycle which lasts more than 95% of the total duration is -", "opts": ["Prophase", "Interphase", "Anaphase", "Telophase"], "ans": 1, "mark": "Imp", "exp": "Interphase lasts more than 95% of the cell cycle."}, {"subject": "Biology", "chapter": "Cell cycle and cell division", "q": "Most dramatic period of cell cycle is -", "opts": ["G1 phase", "G2 phase", "S phase", "M phase"], "ans": 3, "mark": "Imp", "exp": "M phase is the most dramatic phase, with major structural reorganisation of the cell."}, {"subject": "Biology", "chapter": "Cell cycle and cell division", "q": "Two daughter cells formed after mitosis are -", "opts": ["Non-identical to each other", "Identical to each other", "Non-identical to parents", "Irregular in size"], "ans": 1, "mark": "Imp", "exp": "Mitosis gives two daughter cells identical to each other and to the parent."}, {"subject": "Biology", "chapter": "Cell cycle and cell division", "q": "A cell division in which a diploid somatic cell divides into two identical daughter cells is called -", "opts": ["Meiosis I", "Meiosis II", "Mitosis", "Cytokinesis"], "ans": 2, "mark": "Imp", "exp": "Mitosis: a diploid somatic cell gives two identical diploid daughter cells."}, {"subject": "Biology", "chapter": "Cell cycle and cell division", "q": "Which type of cell division is called somatic cell division?", "opts": ["Meiosis I", "Meiosis II", "Reduction division", "Mitosis"], "ans": 3, "mark": "Imp", "exp": "Mitosis is called somatic cell division (equational division)."}, {"subject": "Biology", "chapter": "Cell cycle and cell division", "q": "Mitosis occurs in -", "opts": ["Meristematic cells", "Undifferentiated germ cells", "Somatic cells", "More than one option is correct"], "ans": 3, "mark": "Imp", "exp": "Mitosis occurs in meristematic cells, somatic cells and others, so more than one option is correct."}, {"subject": "Biology", "chapter": "Cell cycle and cell division", "q": "The first phase of mitosis which follows interphase is -", "opts": ["Metaphase", "Prophase", "Telophase", "Anaphase"], "ans": 1, "mark": "Imp", "exp": "Prophase is the first phase of mitosis after interphase."}, {"subject": "Biology", "chapter": "Cell cycle and cell division", "q": "Initiation of condensation of chromatin material occurs in -", "opts": ["Prophase", "Anaphase", "Telophase", "Metaphase"], "ans": 0, "mark": "Imp", "exp": "Chromosome condensation begins in prophase."}, {"subject": "Biology", "chapter": "Cell cycle and cell division", "q": "Mitotic spindle initiates during -", "opts": ["Telophase", "Anaphase", "Prophase", "Metaphase"], "ans": 2, "mark": "Imp", "exp": "Mitotic spindle assembly starts in prophase."}, {"subject": "Biology", "chapter": "Cell cycle and cell division", "q": "Nucleolus and nuclear membrane disappear during -", "opts": ["Anaphase", "Interphase", "Telophase", "Prophase"], "ans": 3, "mark": "Imp", "exp": "Nucleolus and nuclear envelope disappear in prophase."}, {"subject": "Biology", "chapter": "Cell cycle and cell division", "q": "The chromosomes are shortest and thickest during -", "opts": ["Anaphase", "Metaphase", "Telophase", "Interphase"], "ans": 1, "mark": "Imp", "exp": "Chromosomes are shortest and thickest at metaphase (maximum condensation)."}, {"subject": "Biology", "chapter": "Cell cycle and cell division", "q": "The chromosomes align at the equator during -", "opts": ["Interphase", "Prophase", "Metaphase", "Telophase"], "ans": 2, "mark": "Imp", "exp": "Chromosomes align at the equatorial plate in metaphase."}, {"subject": "Biology", "chapter": "Cell cycle and cell division", "q": "Read the following statements. (a) Complete disintegration of the nuclear envelope marks the start of the second phase of mitosis. (b) Metaphase chromosome is made up of one sister chromatid.", "opts": ["Only (b) is correct", "Both (a) & (b) are incorrect", "Only (a) is correct", "Both (a) & (b) are correct"], "ans": 2, "mark": "Imp", "exp": "(a) is correct: complete nuclear envelope breakdown marks the start of metaphase. (b) is wrong: a metaphase chromosome has two sister chromatids."}, {"subject": "Biology", "chapter": "Cell cycle and cell division", "q": "The morphology of the chromosomes is studied during -", "opts": ["Metaphase", "Interphase", "Prophase", "Telophase"], "ans": 0, "mark": "Imp", "exp": "Chromosome morphology is best studied at metaphase."}, {"subject": "Biology", "chapter": "Cell cycle and cell division", "q": "The point of attachment of microtubules on the chromosome is called as -", "opts": ["Centromere", "Kinetochore", "Chromatid", "Spindle"], "ans": 1, "mark": "Imp", "exp": "Kinetochore is the attachment site of spindle microtubules on the chromosome."}, {"subject": "Biology", "chapter": "Cell cycle and cell division", "q": "Chromosomes move towards the pole during -", "opts": ["Prophase", "Metaphase", "Telophase", "Anaphase"], "ans": 3, "mark": "Imp", "exp": "Chromosomes/chromatids move towards the poles in anaphase."}, {"subject": "Biology", "chapter": "Cell cycle and cell division", "q": "The centromere splits during -", "opts": ["Anaphase", "Telophase", "Interphase", "Prophase"], "ans": 0, "mark": "Imp", "exp": "The centromere splits at the start of anaphase."}, {"subject": "Biology", "chapter": "Cell cycle and cell division", "q": "The chromosomes cluster at opposite poles and their identity is lost as discrete elements during -", "opts": ["Telophase", "Anaphase", "Metaphase", "Prophase"], "ans": 0, "mark": "Imp", "exp": "In telophase chromosomes cluster at the poles and lose their identity as discrete elements."}, {"subject": "Biology", "chapter": "Cell cycle and cell division", "q": "The mitotic spindle disappears in -", "opts": ["Prophase", "Metaphase", "Anaphase", "Telophase"], "ans": 3, "mark": "Imp", "exp": "The spindle disappears in telophase."}, {"subject": "Biology", "chapter": "Cell cycle and cell division", "q": "Decondensation of chromosomes occurs during -", "opts": ["Prophase", "Metaphase", "Anaphase", "Telophase"], "ans": 3, "mark": "Imp", "exp": "Chromosomes decondense in telophase."}, {"subject": "Biology", "chapter": "Cell cycle and cell division", "q": "The nuclear envelope reassembles during -", "opts": ["Prophase", "Telophase", "Anaphase", "Metaphase"], "ans": 1, "mark": "Imp", "exp": "The nuclear envelope reassembles around the chromosome clusters in telophase."}, {"subject": "Biology", "chapter": "Cell cycle and cell division", "q": "_________ phase marks the end of M-phase.", "opts": ["Karyokinesis", "Prophase", "Cytokinesis", "Telophase"], "ans": 2, "mark": "Imp", "exp": "Cytokinesis marks the end of M phase."}, {"subject": "Biology", "chapter": "Cell cycle and cell division", "q": "If karyokinesis is not followed by cytokinesis, then gives rise to -", "opts": ["Zygote", "Fertilised egg", "Multinucleate condition", "Embryo"], "ans": 2, "mark": "Imp", "exp": "Karyokinesis not followed by cytokinesis gives a multinucleate condition."}, {"subject": "Biology", "chapter": "Cell cycle and cell division", "q": "A single cell containing large number of nuclei is called -", "opts": ["Syncytium", "Cell plate", "Monad", "Bivalent"], "ans": 0, "mark": "Imp", "exp": "A syncytium is a single cell with many nuclei."}, {"subject": "Biology", "chapter": "Cell cycle and cell division", "q": "A type of cell division which reduces chromosome number to half is -", "opts": ["Mitosis", "Multiple fission", "Fragmentation", "Meiosis"], "ans": 3, "mark": "Imp", "exp": "Meiosis reduces the chromosome number to half."}, {"subject": "Biology", "chapter": "Cell cycle and cell division", "q": "In meiosis-I, condensation and coiling of chromatin fibres started during -", "opts": ["Metaphase", "Leptotene", "Diakinesis", "Diplotene"], "ans": 1, "mark": "Imp", "exp": "Chromatin condensation and coiling starts in leptotene of prophase I."}, {"subject": "Biology", "chapter": "Cell cycle and cell division", "q": "In pachytene, each tetrad contains -", "opts": ["Two chromatids", "One chromatid", "Four chromatids", "Three chromatids"], "ans": 2, "mark": "Imp", "exp": "In pachytene each tetrad (bivalent) has four chromatids."}, {"subject": "Biology", "chapter": "Cell cycle and cell division", "q": "Crossing over occurs during -", "opts": ["Anaphase I", "Leptotene", "Diplotene", "Pachytene"], "ans": 3, "mark": "Imp", "exp": "Crossing over occurs in pachytene."}, {"subject": "Biology", "chapter": "Cell cycle and cell division", "q": "The homologous chromosomes move towards the opposite poles during -", "opts": ["Anaphase I", "Anaphase II", "Leptotene", "Pachytene"], "ans": 0, "mark": "Imp", "exp": "Homologous chromosomes move to opposite poles in anaphase I."}, {"subject": "Biology", "chapter": "Cell cycle and cell division", "q": "_________ marks the site where crossing over had occurred.", "opts": ["Diakinesis", "Synapsis", "Chiasmata", "Leptotene"], "ans": 2, "mark": "Imp", "exp": "Chiasmata mark the sites where crossing over occurred."}, {"subject": "Biology", "chapter": "Cell cycle and cell division", "q": "Terminalisation of chiasmata occurs during -", "opts": ["Prophase-I", "Metaphase-I", "Anaphase-I", "Telophase-I"], "ans": 0, "mark": "Imp", "exp": "Terminalisation of chiasmata occurs in late prophase I (diakinesis)."}, {"subject": "Biology", "chapter": "Cell cycle and cell division", "q": "Bivalent chromosomes align themselves at the equator during -", "opts": ["Metaphase I", "Prophase I", "Metaphase II", "Anaphase II"], "ans": 0, "mark": "Imp", "exp": "Bivalents align at the equator in metaphase I."}, {"subject": "Biology", "chapter": "Cell cycle and cell division", "q": "Major check point of cell cycle is -", "opts": ["G1 → S transition", "S → G1 transition", "G2 → M transition", "M → G2 transition"], "ans": 0, "mark": "Imp", "exp": "G1 to S transition is the major checkpoint of the cell cycle."}, {"subject": "Biology", "chapter": "Cell cycle and cell division", "q": "Which phase of meiosis essentially the reverse of prophase in terms of nuclear changes?", "opts": ["S-phase", "Anaphase", "Telophase", "Interphase"], "ans": 2, "mark": "Imp", "exp": "Telophase is the reverse of prophase: envelope and nucleolus reform and chromosomes decondense."}, {"subject": "Biology", "chapter": "Cell cycle and cell division", "q": "What will be the total number of mitotic divisions in the formation of 64 daughter cells?", "opts": ["6", "32", "63", "16"], "ans": 2, "mark": "Imp", "exp": "One cell to 64 cells needs 63 divisions (n - 1)."}, {"subject": "Biology", "chapter": "Cell cycle and cell division", "q": "If there are 30 chromosomes in G1 phase then what will be number of bivalents in zygotene stage?", "opts": ["30", "15", "45", "60"], "ans": 1, "mark": "Imp", "exp": "2n = 30 means 15 homologous pairs, so 15 bivalents form at zygotene."}, {"subject": "Biology", "chapter": "Cell cycle and cell division", "q": "What will be the amount of DNA in meiosis II products if meiocyte contains 30 Pg DNA in G1 phase?", "opts": ["30 Pg", "60 Pg", "15 Pg", "120 Pg"], "ans": 2, "mark": "Imp", "exp": "30 Pg doubles to 60 in S, 30 per cell after meiosis I, 15 Pg per cell after meiosis II."}, {"subject": "Biology", "chapter": "Cell cycle and cell division", "q": "Which one is correct about bivalent?", "opts": ["Bivalents are tetrad", "A bivalents means two chromatids", "One bivalent consists four homologous chromosome", "Bivalents forms in diplotene"], "ans": 0, "mark": "Imp", "exp": "A bivalent is a pair of homologous chromosomes (tetrad of four chromatids)."}, {"subject": "Biology", "chapter": "Cell cycle and cell division", "q": "Select the correct statement with respect to mitosis.", "opts": ["Chromatids separate but remain in the centre of the cell in anaphase.", "Chromatids start moving towards opposite poles in telophase.", "Golgi complex and endoplasmic reticulum are still visible at the end of prophase.", "Chromosomes move to the spindle equator and get aligned along equatorial plate in metaphase."], "ans": 3, "mark": "Imp", "exp": "In metaphase chromosomes move to the spindle equator and align along the plate; other options describe wrong stages."}, {"subject": "Biology", "chapter": "Cell cycle and cell division", "q": "Match the description (given in column I) with correct stage of prophase I (given in column II) and choose the correct option. Column I: A. Chromosomes are moved to spindle equator; B. Centromere splits and chromatids apart; C. Pairing between homologous chromosomes takes place; D. Crossing between homologous chromosomes. Column II: I. Pachytene; II. Zygotene; III. Anaphase; IV. Metaphase", "opts": ["A-I; B-II; C-III; D-IV", "A-II; B-III; C-IV; D-I", "A-IV; B-III; C-II; D-I", "A-III; B-I; C-IV; D-II"], "ans": 2, "mark": "Imp", "exp": "A-IV (metaphase), B-III (anaphase), C-II (zygotene pairing), D-I (pachytene crossing over)."}, {"subject": "Biology", "chapter": "Cell cycle and cell division", "q": "Given below is a schematic break-up of the phases / stages of cell cycle with few parts labelled as A, B, C & D. Which one of the following is the correct indication of the stage/phase in the cell cycle? [Diagram-based question: Circular cell cycle diagram: Interphase and Mitosis sectors, M phase split into A, B, C; D marked in interphase]", "opts": ["C - Karyokinesis", "D - Synthesis phase", "A - Cytokinesis", "B - Metaphase"], "ans": 1, "mark": "Imp", "exp": "D marks the synthesis (S) phase in the interphase part of the cycle diagram."}, {"subject": "Biology", "chapter": "Cell cycle and cell division", "q": "Which one is correct about bivalent? (i) Bivalent are tetrads. (ii) A bivalent means 4 chromatids and 2 centromere. (iii) One bivalent consists of 2 homologous chromosomes each and sister chromatids. (iv) Bivalents formation occurs in zygotene.", "opts": ["All of these", "Only (iii)", "(iii) and (iv)", "Only (iv)"], "ans": 0, "mark": "Imp", "exp": "All four statements about a bivalent are true."}, {"subject": "Biology", "chapter": "Cell cycle and cell division", "q": "Identify the phases from the graph given below that shows the change in DNA content during various phases (A to D) of mitotic cell cycle. [Diagram-based question: Graph of DNA content (2C to 4C) vs Time with phases A, B, C, D marked]", "opts": ["A-G2, B-G1, C-S, D-M", "A-G2, B-S, C-G1, D-M", "A-G1, B-S, C-G2, D-M", "A-M, B-G1, C-S, D-G2"], "ans": 2, "mark": "Imp", "exp": "DNA is 2C in G1, rises in S, stays 4C in G2 and falls after M: A-G1, B-S, C-G2, D-M."}, {"subject": "Biology", "chapter": "Cell cycle and cell division", "q": "How many meiotic divisions are required to produce 100 pollen grains?", "opts": ["25", "50", "100", "125"], "ans": 0, "mark": "Imp", "exp": "Each meiosis gives 4 pollen grains, so 100/4 = 25 meiotic divisions."}, {"subject": "Biology", "chapter": "Cell cycle and cell division", "q": "Mitosis is the process by which eukaryotic cells -", "opts": ["Expose the genes for protein synthesis", "Become specialized in structure and function", "Multiply", "Grow"], "ans": 2, "mark": "Imp", "exp": "Mitosis is the process by which eukaryotic cells multiply."}, {"subject": "Biology", "chapter": "Cell cycle and cell division", "q": "In meiosis, the daughter cells differ from parent cell as well as amongst themselves due to", "opts": ["Segregation, independent assortment and crossing over", "Segregation and crossing over", "Independent assortment and crossing over", "Segregation and independent assortment"], "ans": 0, "mark": "Imp", "exp": "Segregation, independent assortment and crossing over make daughter cells differ from parent and from each other."}, {"subject": "Biology", "chapter": "Cell cycle and cell division", "q": "Which one of the following precedes re-formation of the nuclear envelope during M phase of the cell cycle?", "opts": ["Condensation from chromosomes, and reassembly of the nuclear lamina.", "Transcription from chromosomes, and re-assembly of the nuclear lamina.", "Formation of the contractile ring, and formation of the phragmoplast.", "Formation of the contractile ring, and transcription from chromosomes."], "ans": 1, "mark": "Imp", "exp": "As per book key (b): chromosome decondensation, transcription and nuclear lamina reassembly come before nuclear envelope re-formation."}, {"subject": "Biology", "chapter": "Cell cycle and cell division", "q": "Match the terms (given in column I) with their explanation (given in column II) and choose the correct combination. Column I (Terms): A. Terminalization; B. Synapsis; C. Chiasmata; D. Synaptonemal complex. Column II (Explanation): I. Pairing of homologous chromosomes; II. Point of attachment between homologous chromosomes; III. Nuclear protein complex that helps in adherence of sister chromatids and then homologous chromosomes; IV. Shifting of chiasmata outwards towards the ends of a bivalent.", "opts": ["A-IV; B-I; C-II; D-III", "A-II; B-III; C-IV; D-I", "A-II; B-IV; C-III; D-I", "A-IV; B-I; C-III; D-II"], "ans": 0, "mark": "Imp", "exp": "A-IV terminalization, B-I synapsis, C-II chiasmata, D-III synaptonemal complex."}, {"subject": "Biology", "chapter": "Cell cycle and cell division", "q": "Which stages of cell division do the following figures A and B represent respectively? [Diagram-based question: Figure A: cell with chromosomes moving to opposite poles with spindle; Figure B: cell with condensed chromosomes, nucleus fading]", "opts": ["A - Metaphase; B - Telophase", "A - Telophase; B - Metaphase", "A - Anaphase; B - Prophase", "A - Prophase; B - Anaphase"], "ans": 2, "mark": "Imp", "exp": "A shows chromatids moving to poles (anaphase); B shows condensed chromosomes with fading nucleus (prophase)."}, {"subject": "Biology", "chapter": "Cell cycle and cell division", "q": "Which one is correct about crossing over/genetic recombination? (i) It occurs in tetrad stage which occurs in pachytene of prophase I of meiosis I. (ii) It occurs between non-sister chromatids of homologous chromosomes. (iii) It is recombinase enzyme mediated process. (iv) It is also the reciprocal transfer of genes between the non-homologous chromosomes", "opts": ["All of the above", "All except (iv)", "(ii), (iii) and (iv)", "(iii) and (iv)"], "ans": 1, "mark": "Imp", "exp": "Crossing over is between non-sister chromatids of homologous chromosomes, not non-homologous ones, so (iv) is wrong."}, {"subject": "Biology", "chapter": "Cell cycle and cell division", "q": "The diagram shows a cell whose diploid chromosome number is four. Which one of the following option shows correct stage of cell? [Diagram-based question: Cell diagram with 2n=4, chromosomes moving towards opposite poles]", "opts": ["Metaphase", "Anaphase of mitosis", "Anaphase I of meiosis", "Anaphase II of meiosis"], "ans": 2, "mark": "Imp", "exp": "Homologues moving apart with chromatids still attached: anaphase I of meiosis."}, {"subject": "Biology", "chapter": "Cell cycle and cell division", "q": "Mitosis and meiosis take place respectively in -", "opts": ["Meristem and gametangia", "Gametangia and meristem", "Permanent tissues and secretory tissues", "Secretory tissues and permanent tissues"], "ans": 0, "mark": "Imp", "exp": "Mitosis occurs in meristem; meiosis in gametangia."}, {"subject": "Biology", "chapter": "Cell cycle and cell division", "q": "The major event that occurs during the anaphase of mitosis, which brings about the equal distribution of chromosomes is -", "opts": ["Replication of the genetic material", "Splitting of the chromatids", "Splitting of the centromeres", "Condensation of the chromatin"], "ans": 2, "mark": "Imp", "exp": "Equal distribution of chromosomes is due to splitting of centromeres in anaphase."}, {"subject": "Biology", "chapter": "Cell cycle and cell division", "q": "The separation of two chromatids of each chromosome at early anaphase is initiated by -", "opts": ["The interaction of centrosome with the chromosomal fibres.", "The elongation of telophasic spindle.", "The force of repulsion between the divided kinetochores.", "All of the above"], "ans": 2, "mark": "Imp", "exp": "Early anaphase separation of chromatids is initiated by repulsion between the divided kinetochores."}, {"subject": "Biology", "chapter": "Cell cycle and cell division", "q": "Which of the following statement is not true for homologous chromosome pairs?", "opts": ["They come from only one of the individual's parents.", "They usually contain slightly different versions of the same genetic information.", "They segregate from each other during meiosis I.", "They synapse during meiosis I."], "ans": 0, "mark": "Imp", "exp": "Homologous pairs come from both parents (one maternal, one paternal), so (a) is not true."}, {"subject": "Biology", "chapter": "Cell cycle and cell division", "q": "Match the description given in column-I with their stapes given in column-II and identify the correct answer. Column-I: A. Initiation of the assembly of mitotic spindle; B. Proteins are synthesized in preparation for mitosis while cell growth continues; C. Spindle fibres attach to kinetochores of chromosomes; D. Movement of chromatids towards opposite poles. Column-II: I. Anaphase; II. Prophase; III. Interphase; IV. Metaphase. The correct match is", "opts": ["A-II; B-III; C-IV; D-I", "A-III; B-II; C-I; D-IV", "A-I; B-III; C-II; D-IV", "A-IV; B-III; C-I; D-II"], "ans": 0, "mark": "Imp", "exp": "A-II prophase, B-III interphase, C-IV metaphase, D-I anaphase."}, {"subject": "Biology", "chapter": "Cell cycle and cell division", "q": "Given below is the representation of a certain event at a particular stage of a type of cell division. Which stage is shown by the given figure? [Diagram-based question: Figure of paired homologous chromosomes with chiasmata/crossing over (X-shaped crossover) transitioning to terminalised bivalent]", "opts": ["Prophase I during meiosis", "Prophase II during meiosis", "Prophase of mitosis", "Both prophase and metaphase of mitosis"], "ans": 0, "mark": "Imp", "exp": "Paired homologues with chiasmata (crossing over) is seen in prophase I of meiosis."}, {"subject": "Biology", "chapter": "Cell cycle and cell division", "q": "Read the following statements about cell division and select the correct statements. (i) M phase represents the phase when actual cell division occurs and I phase represents the phase between two successive M phase. (ii) In the 24 hours, average duration of cell cycle of a human cell, cell division proper lasts for only about an hour. (iii) M phase constitutes more than 95% of the duration of cell cycle.", "opts": ["(i) and (ii)", "(ii) and (iii)", "(i) and (iii)", "(I), (ii) and (iii)"], "ans": 0, "mark": "Imp", "exp": "(i) and (ii) are true; M phase is only ~1 hour while interphase is >95%, so (iii) is false."}, {"subject": "Biology", "chapter": "Cell cycle and cell division", "q": "In the somatic cell cycle -", "opts": ["In G1 phase, DNA content is double the amount of DNA present in the original cell.", "DNA replication takes place in S-phase.", "A short interphase is followed by a long mitotic phase.", "G2 phase follows mitotic phase."], "ans": 1, "mark": "Imp", "exp": "DNA replication takes place in S phase."}, {"subject": "Biology", "chapter": "Cell cycle and cell division", "q": "If you are provided with root-tips of onion in your class and are asked to count the chromosomes, which of the following stages can you most conveniently look into?", "opts": ["Metaphase", "Telophase", "Anaphase", "Prophase"], "ans": 0, "mark": "Imp", "exp": "Metaphase chromosomes are most condensed and easiest to count."}, {"subject": "Biology", "chapter": "Cell cycle and cell division", "q": "In animal cells, cytokinesis involves -", "opts": ["The separation of sister chromatids.", "The contraction of the contractile ring of microfilament.", "Depolymerization of kinetochore microtubules.", "A protein kinase that phosphorylates other enzymes."], "ans": 1, "mark": "Imp", "exp": "Animal cytokinesis occurs by contraction of a microfilament ring forming a furrow."}, {"subject": "Biology", "chapter": "Cell cycle and cell division", "q": "Cell would normally proceed to mitosis without interruption -", "opts": ["Once it has entered the S phase.", "Once it has entered the G2 phase.", "At any time during cell division activity.", "None of the above"], "ans": 0, "mark": "Imp", "exp": "Once a cell enters S phase it normally proceeds to mitosis without interruption."}, {"subject": "Biology", "chapter": "Cell cycle and cell division", "q": "Which of the following statement(s) is/are true?", "opts": ["Cell plate represents the middle lamella between the walls of two adjacents cells.", "At the time of cytokinesis, organelles like mitochondria and plastids get distributed between the daughter cells.", "Cytokinesis in plant cell is centrifugal and takes place by cell-plate formation while animal cells by furrowing/cleavage and is centripetal.", "All of the above"], "ans": 3, "mark": "Imp", "exp": "All three statements are true."}, {"subject": "Biology", "chapter": "Cell cycle and cell division", "q": "Select the correctly matched pair. A. S phase - DNA replication; B. Zygotene - Synapsis; C. Diplotene - Crossing over; D. Meiosis - Both haploid and diploid cells", "opts": ["A and B", "C and D", "B and D", "A and C"], "ans": 0, "mark": "Imp", "exp": "S phase = DNA replication and zygotene = synapsis are correct; crossing over is pachytene."}, {"subject": "Biology", "chapter": "Cell cycle and cell division", "q": "A stage in cell division is shown in the figure. Select the answer which gives correct identification of the stage with its characteristics. [Diagram-based question: Animal cell with two daughter nuclei and furrow/constriction in the middle]", "opts": ["Late anaphase - Chromosomes move away from equatorial plate, Golgi complex is not present.", "Cytokinesis - Cell plate is formed, mitochondria distributed between two daughter cells.", "Telophase - Endoplasmic reticulum and nucleolus not reformed yet", "Telophase - Nuclear envelop reforms, golgi complex reforms"], "ans": 3, "mark": "Imp", "exp": "Late stage with two daughter nuclei: telophase, where nuclear envelope and Golgi reform."}, {"subject": "Biology", "chapter": "Cell cycle and cell division", "q": "Mark the incorrect pair.", "opts": ["Interphase - S-phase", "M phase - Metaphase", "Meiosis I - Diplotene", "Meiosis II - Diakinesis"], "ans": 3, "mark": "Imp", "exp": "Diakinesis is a stage of prophase I of meiosis I, not meiosis II."}, {"subject": "Biology", "chapter": "Cell cycle and cell division", "q": "In which stage of the cell cycle, histone proteins are synthesized in a eukaryotic cell?", "opts": ["During G2 stage of prophase", "During S-phase", "During entire prophase", "During telophase"], "ans": 1, "mark": "Imp", "exp": "Histone proteins are synthesised in S phase along with DNA replication."}, {"subject": "Biology", "chapter": "Cell cycle and cell division", "q": "Which of the following is the result when karyokinesis is not followed by cytokinesis?", "opts": ["Synaptonemal complex", "Syncytium", "Recombination nodules", "Terminalization"], "ans": 1, "mark": "Imp", "exp": "Karyokinesis without cytokinesis gives a syncytium (multinucleate cell)."}, {"subject": "Biology", "chapter": "Cell cycle and cell division", "q": "Which of the following will show simple cell division?", "opts": ["Microspore mother cells", "Megaspore mother cells", "Archesporial cells", "All of the above"], "ans": 2, "mark": "Imp", "exp": "Archesporial cells divide by simple mitotic division; mother cells undergo meiosis."}, {"subject": "Biology", "chapter": "Cell cycle and cell division", "q": "Identify the meiotic stage in which the homologous chromosomes separate while the sister chromatids remain associated at their centromeres.", "opts": ["Metaphase I", "Metaphase II", "Anaphase I", "Anaphase II"], "ans": 2, "mark": "Imp", "exp": "In anaphase I homologues separate while sister chromatids stay joined at centromeres."}, {"subject": "Biology", "chapter": "Cell cycle and cell division", "q": "Significance of mitosis involves -", "opts": ["The growth of multicellular organism.", "Cell repair", "Production of diploid daughter cells with identical genetic complement.", "All of the above"], "ans": 3, "mark": "Imp", "exp": "Mitosis gives growth, cell repair and identical diploid daughter cells."}, {"subject": "Biology", "chapter": "Cell cycle and cell division", "q": "Find the correctly matched pairs and choose the correct option. A. Zygotene - Pairing of homologous chromosomes; B. Pachytene - Dissolution of the complex synaptonemal takes place; C. Diplotene - Bivalent chromosomes appear as tetrads; D. Diakinesis - Terminalization of chiasmata takes place", "opts": ["A and C", "A and D", "A and B", "B and C"], "ans": 1, "mark": "Imp", "exp": "Zygotene = pairing and diakinesis = terminalisation are correct; the other two are mismatched."}, {"subject": "Biology", "chapter": "Cell cycle and cell division", "q": "The following diagram is of a typical cell cycle indicating formation of two cells from one cell. Choose the correct option showing the correct identification of X, Y, & Z. [Diagram-based question: Circular cell cycle diagram with M phase and sectors X, Y, Z]", "opts": ["X - G1; Y - S; Z - G2", "X - G2; Y - S; Z - G1", "X - G0; Y - S; Z - G2", "X - G1; Y - G0; Z - S"], "ans": 0, "mark": "Imp", "exp": "Cell cycle order is G1, S, G2, M: X-G1, Y-S, Z-G2."}, {"subject": "Biology", "chapter": "Cell cycle and cell division", "q": "Which of the following pair is correctly matched?", "opts": ["G1 - Second growth phase", "S - First growth phase", "G2 - Synthesis phase", "G0 - Quiescent stage"], "ans": 3, "mark": "Imp", "exp": "G0 is the quiescent stage."}, {"subject": "Biology", "chapter": "Cell cycle and cell division", "q": "How many times mitotic divisions are needed for a single cell to make 128 cells?", "opts": ["7", "14", "28", "64"], "ans": 0, "mark": "Imp", "exp": "2^7 = 128, so 7 mitotic divisions are needed."}, {"subject": "Biology", "chapter": "Cell cycle and cell division", "q": "Which of the following occurs only once in life cycle of a cell?", "opts": ["Replication of histone.", "Replication of chromosomes.", "Mitosis", "Meiosis"], "ans": 3, "mark": "Imp", "exp": "Meiosis occurs only once in the life cycle of a cell."}, {"subject": "Biology", "chapter": "Cell cycle and cell division", "q": "In Meiosis-", "opts": ["Division of nucleus twice but DNA replicates only once.", "Division of nucleus twice and DNA replicates twice.", "Division of nucleus once and replication of DNA is also once.", "Division of nucleus once and DNA - replication is twice."], "ans": 0, "mark": "Imp", "exp": "Meiosis: two nuclear divisions but a single DNA replication."}, {"subject": "Biology", "chapter": "Cell cycle and cell division", "q": "In telophase of mitosis, the mitotic spindle breaks down and nuclear membranes form. This is essentially the opposite of what happens in -", "opts": ["Prophase", "Interphase", "Metaphase", "S phase"], "ans": 0, "mark": "Imp", "exp": "The telophase events are the opposite of prophase events."}, {"subject": "Biology", "chapter": "Cell cycle and cell division", "q": "Which of the following statement(s) is/are correct about S-phase (synthetic phase)? (i) It occurs between G1 and G2 phase. (ii) It marks the period during which DNA replicates. (iii) At the end of this phase, DNA is doubled but the number of chromosomes remains unchanged. (iv) As the DNA is doubled in this phase number of chromosomes is also doubled. (v) Centrioles replicate in this phase. (vi) Amount of DNA changes from 2C to 4C.", "opts": ["(i), (ii), (iv), (v), (vi)", "(i), (ii), (iii), (v), (vi)", "All of the above", "Only (iv)"], "ans": 1, "mark": "Imp", "exp": "(iv) is false: chromosome number does not double in S phase. All other statements are true."}, {"subject": "Biology", "chapter": "Cell cycle and cell division", "q": "Choose the mismatch pair.", "opts": ["Karyokinesis - Division of centromere", "Cytokinesis - Division of cytoplasm", "S-phase - DNA synthesis", "Synapsis - Pairing of homologous chromosomes"], "ans": 0, "mark": "Imp", "exp": "Karyokinesis is nuclear division, not division of the centromere."}, {"subject": "Biology", "chapter": "Cell cycle and cell division", "q": "A stage of mitosis is shown in the given diagram. Identify stage with its characteristics? [Diagram-based question: Cell with chromosomes aligned at equator with spindle fibres attached]", "opts": ["Late prophase - Chromosomes move to spindle equator.", "Metaphase - Spindle fibres attached to kinetochores, centromeres split and chromatids separate", "Metaphase - chromosomes moved to spindle equator chromosomes made up of two sister chromatids", "Anaphase - centromeres split and chromatids separate and start moving away"], "ans": 2, "mark": "Imp", "exp": "Chromosomes aligned at the equator, each made of two sister chromatids: metaphase."}, {"subject": "Biology", "chapter": "Cell cycle and cell division", "q": "Which of the following pair is correctly matched?", "opts": ["Anaphase I - Homologous chromosomes are separated.", "Metaphase I - Pairing of maternal and paternal chromosomes.", "Interphase - A nuclear envelop encloses each haploid set of chromosomes.", "Prophase I - Non-homologous chromosomes are separated."], "ans": 0, "mark": "Imp", "exp": "In anaphase I homologous chromosomes are separated."}, {"subject": "Biology", "chapter": "Cell cycle and cell division", "q": "During which stages (or prophase I substages) of meiosis do you expect to find the bivalents and DNA replication respectively?", "opts": ["Pachytene and interphase (between two meiotic divisions).", "Pachytene and interphase (just prior to prophase I).", "Pachytene and S phase (of interphase just prior to prophase I).", "Zygotene and S phase (of interphase prior to prophase I)."], "ans": 3, "mark": "Imp", "exp": "Bivalents are seen from zygotene onward (pachytene tetrads); DNA replication is in S phase before prophase I."}, {"subject": "Biology", "chapter": "Cell cycle and cell division", "q": "G0 state of cells in eukaryotic cell cycle denotes -", "opts": ["Check point before entering the next phase.", "Pausing in the middle of a cycle to cope with a temporary delay.", "Death of a cell.", "Exit of cells from cell cycle."], "ans": 3, "mark": "Imp", "exp": "G0 denotes exit of cells from the cell cycle."}, {"subject": "Biology", "chapter": "Cell cycle and cell division", "q": "Four daughter cells formed after meiosis are -", "opts": ["Genetically similar", "Genetically different", "Anucleate", "Multinucleate"], "ans": 1, "mark": "Imp", "exp": "Crossing over and independent assortment make the four cells genetically different."}, {"subject": "Biology", "chapter": "Cell cycle and cell division", "q": "At which stage, the homologous chromosomes separate due to repulsion, but are yet held by chiasmata?", "opts": ["Zygotene", "Pachytene", "Diplotene", "Diakinesis"], "ans": 2, "mark": "Imp", "exp": "In diplotene homologues repel each other but remain held by chiasmata."}, {"subject": "Biology", "chapter": "Cell cycle and cell division", "q": "Which of the following statements related to G0 stage of the cell cycle are correct? (i) It is a quiescent stage. (ii) In this phase, cell cycle is stopped. (iii) G0 cells do not grow or proliferate but metabolically active. (iv) G0 cells can divide in response to some stimulus.", "opts": ["(i), and (ii)", "(i), (ii) and (iii)", "Only (i) and (iv)", "All of the above"], "ans": 3, "mark": "Imp", "exp": "All four statements describe G0 correctly."}, {"subject": "Biology", "chapter": "Cell cycle and cell division", "q": "Find out the wrongly matched pair of the stage of prophase I with their feature.", "opts": ["Zygotene - Synaptonemal complex", "Pachytene - Mutation", "Diplotene - Chiasmata", "Diakinesis - Terminalization"], "ans": 1, "mark": "Imp", "exp": "Mutation is not a feature of pachytene (crossing over is)."}, {"subject": "Biology", "chapter": "Cell cycle and cell division", "q": "Choose the diagram which correctly depicts anaphase II. [Diagram-based question: Four cell diagrams as options (a)-(d); options are images only]", "opts": ["Diagram (a)", "Diagram (b)", "Diagram (c)", "Diagram (d)"], "ans": 3, "mark": "Imp", "exp": "Anaphase II shows sister chromatids moving to opposite poles in each haploid cell."}, {"subject": "Biology", "chapter": "Cell cycle and cell division", "q": "Identify the given figures (A, B & C) showing meiotic phases and select the correct option. [Diagram-based question: Three cell figures A, B, C]", "opts": ["A-Metaphase, B-Anaphase, C-Telophase", "A-Metaphase-I, B-Anaphase-I, C-Telophase-I", "A-Metaphase-II, B-Anaphase-II, C-Telophase-II", "A-Anaphase-I, B-Metaphase-I, C-Telophase-I"], "ans": 1, "mark": "Imp", "exp": "A: bivalents at the equator (metaphase I); B: homologues moving apart (anaphase I); C: two cells formed (telophase I)."}, {"subject": "Biology", "chapter": "Cell cycle and cell division", "q": "Significance of meiosis lies in -", "opts": ["Reduction of chromosome number to one half.", "Maintaining consistency of chromosome number during sexual reproduction.", "Production of genetic variability.", "All of the above"], "ans": 3, "mark": "Imp", "exp": "Meiosis halves chromosome number, keeps it constant across generations and creates variability."}, {"subject": "Biology", "chapter": "Cell cycle and cell division", "q": "Mitosis occurs in -", "opts": ["Haploid individuals", "Diploid individuals", "Both (a) and (b)", "In bacteria only"], "ans": 2, "mark": "Imp", "exp": "Mitosis occurs in both haploid and diploid individuals."}, {"subject": "Biology", "chapter": "Cell cycle and cell division", "q": "Number of bivalents are 8 in prophase I. What is the number of chromosomes during anaphase II?", "opts": ["8", "4", "13", "32"], "ans": 0, "mark": "Imp", "exp": "Key gives (a) 8. Strictly, 2n = 16 so a cell in anaphase II has 16 chromosomes (8 per pole): verify with your teacher."}, {"subject": "Biology", "chapter": "Cell cycle and cell division", "q": "Which of the following statements are correct for a growth of organism? (i) All organisms, even the largest, start their life from a single cell. (ii) Growth and reproduction are characteristics of cells. (iii) Cycles of growth and division allow a single cell to form a structure consisting of millions of cells. (iv) Cell division is a very important process in only higher living organisms. (v) During the division of a cell, DNA replication and cytoplasmic increase also take place. (vi) The sequence of events in which cell division, DNA replication and cell growth takes place, is called cell cycle.", "opts": ["(i), (ii), (iii) and (vi)", "(i), (ii), (iv) and (vi)", "(i), (ii), (iii), (v) and (vi)", "(i), (iv) and (vi)"], "ans": 2, "mark": "Imp", "exp": "(iv) is false: cell division is important in all organisms. The rest are true."}, {"subject": "Biology", "chapter": "Cell cycle and cell division", "q": "Which of the following statements is true regarding cell cycle? (i) Cell growth (in terms of cytoplasmic increase) is a continuous process. (ii) DNA synthesis occurs only during one specific stage in the cell cycle. (iii) The replicated chromosomes (DNA) are distributed to daughter nuclei. (iv) Human cells divide once in approximately every 90 minutes. (v) Duration of cell cycle can vary from organism to organism and also from cell type to cell type. (vi) Cell cycle in yeast completed in about 24 hours.", "opts": ["(i), (ii), (iii), (v) and (vi)", "(i), (ii), (iv) and (vi)", "(i), (ii), (iii) and (v)", "(iv) and (vi)"], "ans": 2, "mark": "Imp", "exp": "(iv) and (vi) are false: human cells divide in ~24 h and yeast in ~90 min."}, {"subject": "Biology", "chapter": "Cell cycle and cell division", "q": "Which of the following statements is false regarding cell division? (i) The interphase lasts more than 95% of the duration of cell cycle. (ii) The M-phase starts with the nuclear division, corresponding to the separation of daughter chromosomes. (iii) The M-phase usually ends with division of cytoplasm. (iv) Resting phase, is the time during which the cell is preparing for division by undergoing both cell growth and DNA replication in an orderly manner. (v) In human cell, cell division proper lasts for only about an hour. (vi) Cell cycle in yeast completed in about 90 minutes.", "opts": ["(i), (ii) and (iii)", "(iv) and (v)", "(v) and (vi)", "None of the above"], "ans": 3, "mark": "Imp", "exp": "All given statements are true as per NCERT, so none is false."}, {"subject": "Biology", "chapter": "Cell cycle and cell division", "q": "Which of the following statements are true regarding interphase? (i) It is divided into G1, G2 and S-phase (ii) During G1-phase the cell is metabolically active and continuously grows but does not replicate its DNA. (iii) During S or synthesis phase DNA synthesis or replication takes place. (iv) If the initial amount of DNA is denoted as 2C then it increases to 4C. (v) There is doubling in the chromosome number. (vi) Initial amount of chromosome is denoted as 2n then it increases to 4n.", "opts": ["(i), (ii) and (iii)", "(i), (ii), (iv) and (v)", "(i), (ii), (iii), (v) and (vi)", "(i), (ii), (iii) and (iv)"], "ans": 3, "mark": "Imp", "exp": "(v) and (vi) are false: chromosome number does not double in S phase."}, {"subject": "Biology", "chapter": "Cell cycle and cell division", "q": "Which of the following statements are wrong regarding synthesis phase? (i) Period during which DNA synthesis or replication takes place. (ii) During this time the amount of DNA per cell not changes. (iii) If the initial amount of DNA is denoted as 2C then it increases to 4C. (iv) No increase in the chromosome number. (v) Centriole duplicates in the cytoplasm. (vi) It is a quiescent stage.", "opts": ["(i), (ii) and (iii)", "(ii) and (vi)", "(i), (ii) and (iv)", "(ii) and (iii)"], "ans": 1, "mark": "Imp", "exp": "(ii) and (vi) are wrong: DNA amount doubles in S phase and S phase is not quiescent."}, {"subject": "Biology", "chapter": "Cell cycle and cell division", "q": "Which of the following statements are true for prophase? (i) Initiation of condensation of chromosomal material. (ii) The centriole begins to move towards opposite poles of the cell. (iii) Chromosomes are seen and composed of two chromatids attached together at the centromere. (iv) Initiation of the assembly of mitotic spindle, the microtubules. (v) Cells at the end of prophase, do not show golgi complexes, endoplasmic reticulum, nucleolus and the nuclear envelope. (vi) Spindle fibres attach to kinetochores of chromosomes.", "opts": ["(i), (ii) and (iii)", "(i), (ii), (iv) and (v)", "(i), (ii), (iii), (v) and (vi)", "All except (vi)"], "ans": 3, "mark": "Imp", "exp": "All except (vi): spindle fibres attach to kinetochores at metaphase."}, {"subject": "Biology", "chapter": "Cell cycle and cell division", "q": "Which of the following statements are true for metaphase? (i) By this stage, condensation of chromosomes is not completed. (ii) Morphology of chromosomes is most easily studied. (iii) At this stage, metaphase chromosome is made up of two sister chromatids, which are held together by the centromere. (iv) The plane of alignment of the chromosomes at metaphase is referred to as the metaphase plate. (v) Spindle fibres attach to kinetochores of chromosomes and centromere divides. (vi) Chromosomes are moved to spindle equator and get aligned along metaphase plate through spindle fibres to both poles.", "opts": ["(i), (ii), (iii) and (vi)", "(ii), (iii), (iv) and (vi)", "(i), (ii), (iii), (iv) and (vi)", "(ii), (iii), (v) and (vi)"], "ans": 1, "mark": "Imp", "exp": "(i) and (v) are wrong: condensation is complete by metaphase and the centromere divides at anaphase."}, {"subject": "Biology", "chapter": "Cell cycle and cell division", "q": "Which of the following statements are true for telophase? (i) Centromeres split and chromatids separate. (ii) Chromatids move to opposite spindle poles. (iii) Chromosomes cluster at opposite spindle poles and their identity is lost as discrete elements. (iv) Nuclear envelope assembles around the chromosome clusters. (v) Nucleolus, golgi complex and ER reform. (vi) The individual chromosomes can no longer be seen and chromatin material tends to collect in a mass in the two poles.", "opts": ["(i), (ii), (iii) and (vi)", "(iii), (iv), (v) and (vi)", "(ii) and (iii)", "(ii), (iii), (v) and (vi)"], "ans": 1, "mark": "Imp", "exp": "(i) and (ii) belong to anaphase; (iii) to (vi) describe telophase."}, {"subject": "Biology", "chapter": "Cell cycle and cell division", "q": "Which of the following is key features of meiosis? (i) Meiosis involves two sequential cycles of nuclear and cell division called meiosis-I and meiosis-II. (ii) Meiosis-I is initiated after the parental chromosomes have replicated to produce identical sister chromatids at the S-phase. (iii) Meiosis involves pairing of homologous chromosomes and recombination between them. (iv) Four haploid cells are formed at the end of meiosis-II. (v) Two cycle of DNA replication occurs.", "opts": ["(i), (ii), (iii) and (v)", "(ii), (iii), (iv) and (v)", "(i), (ii), (iii) and (iv)", "(ii), (iii), (iv) and (v)"], "ans": 2, "mark": "Imp", "exp": "Meiosis has only one DNA replication, so (v) is false."}, {"subject": "Biology", "chapter": "Cell cycle and cell division", "q": "Which of the following is true for crossing over? (i) Crossing over is the exchange of material between two homologous chromatids. (ii) Crossing over is also an enzyme-mediated process and the enzyme involved is called recombinase. (iii) Crossing over leads to recombination of genetic material on the two chromosomes. (iv) Recombination between homologous chromosomes is completed by the end of diplotene. (v) Crossing over started in pachytene. (vi) It is responsible for variation in organism.", "opts": ["(i), (ii), (iii) and (v)", "(ii), (iii), (iv) and (v)", "(i), (ii), (iii) and (iv)", "(ii), (iii), (v) and (vi)"], "ans": 3, "mark": "Imp", "exp": "(ii), (iii), (v), (vi) are true; (i) and (iv) are false as per key."}, {"subject": "Biology", "chapter": "Cell cycle and cell division", "q": "Statement I : Human cells divide once in approximately every 24 hours. Statement II : Duration of cell cycle is same in every organism.", "opts": ["Both statements are correct", "Statement I is correct & II is incorrect", "Statement I is incorrect & II is correct", "Both statements are incorrect"], "ans": 1, "mark": "Imp", "exp": "Human cells divide about every 24 h; cycle duration varies among organisms."}, {"subject": "Biology", "chapter": "Cell cycle and cell division", "q": "Statement I : Interphase represents the phase between two successive M phases. Statement II : The mitosis phase is also called resting phase.", "opts": ["Both statements are correct", "Statement I is correct & II is incorrect", "Statement I is incorrect & II is correct", "Both statements are incorrect"], "ans": 1, "mark": "Imp", "exp": "Interphase is the phase between M phases; mitosis (M phase) is not the resting phase."}, {"subject": "Biology", "chapter": "Cell cycle and cell division", "q": "Statement I : During S phase, chromosome number per cell doubles. Statement II : During S phase, centriole duplicate in the nucleoplasm.", "opts": ["Both statements are correct", "Statement I is correct & II is incorrect", "Statement I is incorrect & II is correct", "Both statements are incorrect"], "ans": 3, "mark": "Imp", "exp": "Chromosome number does not double in S phase, and centriole duplicates in the cytoplasm."}, {"subject": "Biology", "chapter": "Cell cycle and cell division", "q": "Statement I : Cells during G0 stage remain metabolically inactive but can proliferate. Statement II : Plants can show mitotic divisions in both haploid and diploid cells.", "opts": ["Both statements are correct", "Statement I is correct & II is incorrect", "Statement I is incorrect & II is correct", "Both statements are incorrect"], "ans": 2, "mark": "Imp", "exp": "G0 cells are metabolically active but do not proliferate, so I is wrong; plants show mitosis in haploid and diploid cells."}, {"subject": "Biology", "chapter": "Cell cycle and cell division", "q": "Statement I : Mitosis is also called as equational division. Statement II : Prophase is marked by the initiation of condensation of chromosomal material.", "opts": ["Both statements are correct", "Statement I is correct & II is incorrect", "Statement I is incorrect & II is correct", "Both statements are incorrect"], "ans": 0, "mark": "Imp", "exp": "Both statements are correct."}, {"subject": "Biology", "chapter": "Cell cycle and cell division", "q": "Statement I : In prophase, chromosomes are seen to be composed of two chromatids attached together at the centromere. Statement II : Cells at the end of prophase, do not show golgi complex, ER nucleolus & nuclear envelope.", "opts": ["Both statements are correct", "Statement I is correct & II is incorrect", "Statement I is incorrect & II is correct", "Both statements are incorrect"], "ans": 0, "mark": "Imp", "exp": "Both statements are correct."}, {"subject": "Biology", "chapter": "Cell cycle and cell division", "q": "Statement I : The complete disintegration of the nuclear envelope marks the start of metaphase. Statement II : Small disc shaped structures at the surface of the centromeres are called kinetochore.", "opts": ["Both statements are correct", "Statement I is correct & II is incorrect", "Statement I is incorrect & II is correct", "Both statements are incorrect"], "ans": 0, "mark": "Imp", "exp": "Both statements are correct."}, {"subject": "Biology", "chapter": "Cell cycle and cell division", "q": "Statement I : Metaphase is characterized by metaphase plate. Statement II : Anaphase is characterized by decondensation of chromosomes.", "opts": ["Both statements are correct", "Statement I is correct & II is incorrect", "Statement I is incorrect & II is correct", "Both statements are incorrect"], "ans": 1, "mark": "Imp", "exp": "Decondensation occurs in telophase, not anaphase."}, {"subject": "Biology", "chapter": "Cell cycle and cell division", "q": "Statement I : Nucleolus, ER and golgi complex reform during anaphase. Statement II : Cell-plate is the precursor of middle lamella.", "opts": ["Both statements are correct", "Statement I is correct & II is incorrect", "Statement I is incorrect & II is correct", "Both statements are incorrect"], "ans": 2, "mark": "Imp", "exp": "Nucleolus, ER and Golgi reform in telophase; cell plate is the precursor of middle lamella."}, {"subject": "Biology", "chapter": "Cell cycle and cell division", "q": "Statement I : Meiosis involves two sequential cycles of nuclear & cell division. Statement II : Four haploid cells are formed at the end of meiosis I.", "opts": ["Both statements are correct", "Statement I is correct & II is incorrect", "Statement I is incorrect & II is correct", "Both statements are incorrect"], "ans": 1, "mark": "Imp", "exp": "Four haploid cells form only at the end of meiosis II."}, {"subject": "Biology", "chapter": "Cell cycle and cell division", "q": "Statement I : Synapsis occur during zygotene stage of prophase I of meiosis I. Statement II : Crossing over is the exchange of genetic material between two non-homologous chromosomes.", "opts": ["Both statements are correct", "Statement I is correct & II is incorrect", "Statement I is incorrect & II is correct", "Both statements are incorrect"], "ans": 1, "mark": "Imp", "exp": "Crossing over is between non-sister chromatids of homologous chromosomes."}, {"subject": "Biology", "chapter": "Cell cycle and cell division", "q": "Statement I : Crossing over is non enzymatic process. Statement II : The final stage of meiotic prophase I is diakinesis.", "opts": ["Both statements are correct", "Statement I is correct & II is incorrect", "Statement I is incorrect & II is correct", "Both statements are incorrect"], "ans": 2, "mark": "Imp", "exp": "Crossing over is enzyme mediated (recombinase); diakinesis is the last stage of prophase I."}, {"subject": "Biology", "chapter": "Cell cycle and cell division", "q": "Assertion : Duration of cell cycle can vary from organism to organism and also from cell type to cell type. Reason : Human cells in culture divide once in approximately every 24 hours.", "opts": ["Assertion and reason both are true and the reason is correct explanation of assertion.", "Assertion and reason both are true but reason is not correct explanation of assertion.", "Assertion is true but reason is wrong.", "Assertion and reason both are wrong."], "ans": 1, "mark": "Imp", "exp": "Both true, but 24 h in human cells does not explain variation among organisms."}, {"subject": "Biology", "chapter": "Cell cycle and cell division", "q": "Assertion : S or synthesis phase marks the period during which amount of DNA per cell doubles. Reason : Increase in the chromosome number; if the cell had diploid or 2n number of chromosomes at G1, after S-phase the number of chromosomes becomes 4n.", "opts": ["Assertion and reason both are true and the reason is correct explanation of assertion.", "Assertion and reason both are true but reason is not correct explanation of assertion.", "Assertion is true but reason is wrong.", "Assertion and reason both are wrong."], "ans": 2, "mark": "Imp", "exp": "DNA doubles in S phase but chromosome number does not."}, {"subject": "Biology", "chapter": "Cell cycle and cell division", "q": "Assertion : In plant cells, during the S-phase, DNA replication begins in the nucleus, and the centriole duplicates in the cytoplasm. Reason : During the G0-phase, proteins are synthesised in preparation for mitosis while cell growth continues.", "opts": ["Assertion and reason both are true and the reason is correct explanation of assertion.", "Assertion and reason both are true but reason is not correct explanation of assertion.", "Assertion is true but reason is wrong.", "Assertion and reason both are wrong."], "ans": 3, "mark": "Imp", "exp": "Higher plant cells lack centrioles, and protein synthesis for mitosis occurs in G2, not G0."}, {"subject": "Biology", "chapter": "Cell cycle and cell division", "q": "Assertion : Mitosis is an equational division. Reason : Number of chromosomes in the parent and progeny cells is the same.", "opts": ["Assertion and reason both are true and the reason is correct explanation of assertion.", "Assertion and reason both are true but reason is not correct explanation of assertion.", "Assertion is true but reason is wrong.", "Assertion and reason both are wrong."], "ans": 0, "mark": "Imp", "exp": "Mitosis is equational because parent and progeny have the same chromosome number."}, {"subject": "Biology", "chapter": "Cell cycle and cell division", "q": "Assertion : Meiosis increases the genetic variability in the population of organisms from one generation to the next. Reason : Meiosis involves pairing of homologous chromosomes and recombination between them.", "opts": ["Assertion and reason both are true and the reason is correct explanation of assertion.", "Assertion and reason both are true but reason is not correct explanation of assertion.", "Assertion is true but reason is wrong.", "Assertion and reason both are wrong."], "ans": 0, "mark": "Imp", "exp": "Pairing of homologues and recombination create genetic variability."}, {"subject": "Biology", "chapter": "Cell cycle and cell division", "q": "Assertion : Meiosis ensures the production of haploid phase in the life cycle of sexually reproducing organisms whereas fertilisation restores the diploid phase. Reason : Four haploid cells are formed at the end of meiosis which are similar to each others.", "opts": ["Assertion and reason both are true and the reason is correct explanation of assertion.", "Assertion and reason both are true but reason is not correct explanation of assertion.", "Assertion is true but reason is wrong.", "Assertion and reason both are wrong."], "ans": 2, "mark": "Imp", "exp": "Meiosis produces genetically different haploid cells; the reason is wrong."}, {"subject": "Biology", "chapter": "Cell cycle and cell division", "q": "Assertion : Meiosis-I is reductional division while meiosis-II is equational division. Reason : In meiosis-I chromosome numbers become half in compare to parental cell while in meiosis-II no change in chromosome number.", "opts": ["Assertion and reason both are true and the reason is correct explanation of assertion.", "Assertion and reason both are true but reason is not correct explanation of assertion.", "Assertion is true but reason is wrong.", "Assertion and reason both are wrong."], "ans": 0, "mark": "Imp", "exp": "Meiosis I is reductional and meiosis II equational, as the reason explains."}, {"subject": "Biology", "chapter": "Cell cycle and cell division", "q": "Assertion : Meiosis is the mechanism by which conservation of specific chromosome number of each species is achieved across generations in sexually reproducing organisms. Reason : In meiosis reduction of chromosome number occurs by half.", "opts": ["Assertion and reason both are true and the reason is correct explanation of assertion.", "Assertion and reason both are true but reason is not correct explanation of assertion.", "Assertion is true but reason is wrong.", "Assertion and reason both are wrong."], "ans": 0, "mark": "Imp", "exp": "Meiosis halves chromosome number, conserving it across generations with fertilisation."}, {"subject": "Biology", "chapter": "Cell cycle and cell division", "q": "Mark the given statements True (T) or False (F). (i) Any sexually reproducing organism starts its life cycle from a single-celled zygote. (ii) The stages through which a cell passed from one division to the next is called cell cycle. (iii) Yeast progresses through the cell cycle in 190 minute. (iv) The cell cycle is divided into two phase interphase and M-Phase. (v) Nuclear division is known as karyokinesis while cytoplasm division is known as cytokinesis. (vi) In cell cycle, the resting phase during which cell is preparing for cell division is called interphase. (vii) G2 phase of M-phase is period when cell grows and carries out normal metabolism. (viii) During S phase of interphase, amount of DNA per cell doubles. (ix) If the cell has 2n number of chromosome at G1, then number of chromosome after S phase will be 4n. (x) G1 phase of cell cycle is called quiescent stage. (xi) During prophase phase of M-phase of cell cycle, duplicated centriole begins to move towards metaphase plate. (xii) Kinetochores structure on surface of centromere serve as the sites of attachment of spindle fibres to the chromosome. Choose the correct option given below :", "opts": ["TFTT-TFTT-FFTT", "TTFT-TTFT-FTFT", "TTFT-FTTF-TFTF", "TFTT-FTTF-TFFT"], "ans": 1, "mark": "Imp", "exp": "Correct: TTFT-TTFT-FTFT. False ones: (iii) 90 min not 190, (vii) G2 is not when cell grows normally in M phase, (ix) number stays 2n, (xi) centrioles move to poles; (x) is the quiescent (G0) stage."}, {"subject": "Biology", "chapter": "Cell cycle and cell division", "q": "Fill in the blanks and choose the correct option given below. (i) The plane of alignment of chromosome at metaphase is referred to as the _A_. (ii) _B_ stage of M-phase is characterised by splitting of centromeres and seperation of chromatids. (iii) Nuclear envelope assembles around chromosome cluster in _C_ stage of M-phase. (iv) During cytokinesis in plant cell, formation of cell plate occur that represent _D_ between the walls of two adjacent cells. (v) During _E_ stage of Prophase I, chromosome start pairing together. This process of association is called _F_. (vi) During zygotene stage, the complex formed by a pair of synapsed Homologous chromosome is called a _G_. (vii) Crossing over occur during _H_ stage of Prophase I and is enzyme-mediated process and enzyme involved is called _I_. (viii) The site of crossover is X-shaped strcuture called _J_ in diplotene stage. (ix) Mitosis is also called _K_ whereas meiosis is called _L_. (x) Number of daughter cell form after mitosis is _M_ and after meiosis is _N_. (xi) Crossing-over occurs between _O_ chromatids of homologous chromosome.", "opts": ["A-metaphase plate, C-Telephase, E-Zygotene, G-tetrad", "B-Anaphase, F-Synapsis, H-Diplotene, J-Chiasmata", "C-Anaphase, J-Chiasmata, L-reductional, M-2", "A-metaphase plate, D-Middle lamellae, N-4, O-non-sister"], "ans": 3, "mark": "Imp", "exp": "A metaphase plate, D middle lamella, N 4 daughter cells, O non-sister chromatids."}, {"subject": "Biology", "chapter": "Cell cycle and cell division", "q": "Match the column I with column II and choose the correct option given below. Column I: A. Centromere splits and chromatids separate apart; B. Pairing between homologous chromosomes takes place; C. Chiasmata; D. Synaptonemal complex. Column II: I. Zygotene; II. Point of attachment between homologous chromosome; III. Nuclear protein complex that helps in adherence of sister chromatids and then homologous chromosomes; IV. Anaphase", "opts": ["A-III; B-I; C-II; D-IV", "A-I; B-IV; C-III; D-II", "A-IV; B-I; C-II; D-III", "A-II; B-III; C-IV; D-I"], "ans": 2, "mark": "Imp", "exp": "A-IV anaphase, B-I zygotene, C-II chiasmata, D-III synaptonemal complex."}, {"subject": "Biology", "chapter": "Cell cycle and cell division", "q": "Which one of the following statements are correct? (i) Chromatids start moving towards opposite poles in anaphase. (ii) Crossing over occurs between non-sister chromatids of homologous chromosomes. (iii) Crossing over occurs in tetrad stage which occurs in pachytene of prophase I of meiosis I. (iv) Chromosomes move to the spindle equator and get aligned along equatorial plate in metaphase. (v) Crossing over is the reciprocal transfer of genes between the non-homologous chromosomes (vi) M phase represents the phase when actual cell division occurs and I phase represents the phase between two successive M phase. (vii) In the 24 hours, average duration of cell cycle of a human cell, cell division proper lasts for only about an hour. (viii) M phase constitutes more than 95% of the duration of cell cycle.", "opts": ["(i), (ii), (v), (vi), (viii)", "(ii), (iv), (vi), (vii), (viii)", "(i), (ii), (iii), (vi), (vii)", "(ii), (iii), (iv), (v), (vi)"], "ans": 2, "mark": "Imp", "exp": "(i), (ii), (iii), (vi), (vii) are true; (v) and (viii) are false as per key."}];
window.PRACTICE_SHEET_DATA["allen_basic_math"] = [{"subject": "Physics", "chapter": "Basic Mathematics used in Physics", "q": "Sunrays cast 4√3 m long shadow of a pole, when sun is 30° above the horizontal. When sun rises to 60° above the horizontal, length of the shadow becomes", "opts": ["4/√3 m", "2√3 m", "2 m", "2√2 m"], "ans": 0, "mark": "Imp", "exp": "Height = 4√3 tan30° = 4 m. New shadow = 4/tan60° = 4/√3 m."}, {"subject": "Physics", "chapter": "Basic Mathematics used in Physics", "q": "An airplane takes off at an angle 30° with the horizontal ground traveling at the speed of 180 km/h. If it continues to fly with the same velocity in the same direction, how long will it take to reach an altitude of 9 km above the ground :-", "opts": ["5 min.", "6 min.", "8 min.", "9 min."], "ans": 1, "mark": "Imp", "exp": "Vertical speed = 180 sin30° = 90 km/h, so t = 9/90 h = 0.1 h = 6 min."}, {"subject": "Physics", "chapter": "Basic Mathematics used in Physics", "q": "The values of sinθ1, cos²θ2 and tanθ3 are given as 1/2, −1/2 and 3 (not in order), for some angles θ1, θ2 and θ3. Choose correct option :-", "opts": ["sinθ1 = 1/2, cos²θ2 = 3, tanθ3 = −1/2", "sinθ1 = −1/2, cos²θ2 = 1/2, tanθ3 = 3", "sinθ1 = 1/2, cos²θ2 = −1/2, tanθ3 = 3", "sinθ1 = −1/2, cos²θ2 = 3, tanθ3 = 1/2"], "ans": 1, "mark": "Imp", "exp": "cos² cannot be negative or greater than 1, so cos²θ2 = 1/2; sin can be −1/2; tan can be 3."}, {"subject": "Physics", "chapter": "Basic Mathematics used in Physics", "q": "The bottom of an electric pole of height 30m is situated at a distance of 30√3 m from you due 60° North of East. The magnitude of the position vector of a crow sitting on the top of the pole relative to you is", "opts": ["30 m", "30√3 m", "60 m", "50 m"], "ans": 2, "mark": "Imp", "exp": "|r| = √((30√3)² + 30²) = √(2700 + 900) = 60 m."}, {"subject": "Physics", "chapter": "Basic Mathematics used in Physics", "q": "A normal human eye can see an object making an angle of 1.8° at the eye. What is the min. height of object which can be seen by an eye placed at a distance of 1 m from the object ?", "opts": ["π/2 cm", "π cm", "π/4 cm", "2π cm"], "ans": 1, "mark": "Imp", "exp": "h = distance × angle(rad) = 100 cm × (1.8 × π/180) = π cm.", "img": "images/physics/ch1_q5.png"}, {"subject": "Physics", "chapter": "Basic Mathematics used in Physics", "q": "In the following figure the curve represents the function", "opts": ["y = a − e^(−x)", "y = a(1 + e^(−x))", "y = a(1 − e^(−x))", "y = e^x"], "ans": 2, "mark": "Imp", "exp": "Curve starts at 0 (x=0) and rises to saturate at a: y = a(1 − e^(−x)).", "img": "images/physics/ch1_q6.png"}, {"subject": "Physics", "chapter": "Basic Mathematics used in Physics", "q": "In the following figures, a pair of curves is shown. In which of them the solid and the dashed curves represent function y1 = 2 sin(πx) and y2 = 4 sin(2πx)", "opts": ["Figure (1)", "Figure (2)", "Figure (3)", "Figure (4)"], "ans": 2, "mark": "Imp", "exp": "y1 has amplitude 2 and period 2; y2 has amplitude 4 and period 1 (twice as many cycles).", "img": "images/physics/ch1_q7.png"}, {"subject": "Physics", "chapter": "Basic Mathematics used in Physics", "q": "The graph of function y = 1 + cos x will be", "opts": ["Graph (1)", "Graph (2)", "Graph (3)", "None of these"], "ans": 0, "mark": "Imp", "exp": "At x=0, y=2; at π/2, y=1; at π, y=0; at 2π, y=2 (cosine shifted up by 1).", "img": "images/physics/ch1_q8.png"}, {"subject": "Physics", "chapter": "Basic Mathematics used in Physics", "q": "Which of the following graph is/are straight line for the equation y² = 2x? I. Graph: y versus x²  II. Graph: y² versus x  III. Graph: y versus √x  IV. Graph: √y versus x", "opts": ["I, IV", "II, III", "I, III", "Only II"], "ans": 1, "mark": "Imp", "exp": "y² = 2x is linear in y² vs x, and y = √2·√x is linear in y vs √x."}, {"subject": "Physics", "chapter": "Basic Mathematics used in Physics", "q": "Which of the following statement is false based on graphs of y versus x as shown below?", "opts": ["Slope at x0 is positive in graph (i) and (ii)", "Slope is constant in graph (iii)", "Slope at x0 is negative in graph (iv)", "Slope at x0 is negative in graph (ii)"], "ans": 3, "mark": "Imp", "exp": "Graph (ii) is rising, so its slope at x0 is positive, not negative.", "img": "images/physics/ch1_q10.png"}, {"subject": "Physics", "chapter": "Basic Mathematics used in Physics", "q": "In the given figure, a function y = 9 sin(3πx) is shown. What is the numerical value of expression A(B + C) ?", "opts": ["5", "3", "9", "6"], "ans": 3, "mark": "Imp", "exp": "A = 9; first peak at 3πx = π/2 gives B = 1/6; minimum at 3πx = 3π/2 gives C = 1/2. A(B+C) = 9 × 2/3 = 6.", "img": "images/physics/ch1_q11.png"}, {"subject": "Physics", "chapter": "Basic Mathematics used in Physics", "q": "A stone is dropped into a quiet lake and waves move in circles spreading out radially at the speed of 5 cm/s. At the instant when the radius of the circular wave is 8 cm, how fast is the enclosed area increasing?", "opts": ["80π cm²/s", "90π cm²/s", "85π cm²/s", "40π cm²/s"], "ans": 0, "mark": "Imp", "exp": "dA/dt = 2πr(dr/dt) = 2π × 8 × 5 = 80π cm²/s."}, {"subject": "Physics", "chapter": "Basic Mathematics used in Physics", "q": "A particle moves along the curve 12y = x³. Which coordinate changes at faster rate at x=10?", "opts": ["x–coordinate", "y–coordinate", "Both x and y–coordinate", "Data insufficient"], "ans": 1, "mark": "Imp", "exp": "12 dy/dt = 3x² dx/dt, so dy/dt = (x²/4) dx/dt = 25 dx/dt. y changes faster."}, {"subject": "Physics", "chapter": "Basic Mathematics used in Physics", "q": "Figure shows the graph of the curve y = (1/3)x³. Which of the following shows the variation of slope of the curve with x coordinate ?", "opts": ["Graph (1)", "Graph (2)", "Graph (3)", "Graph (4)"], "ans": 2, "mark": "Imp", "exp": "dy/dx = x², a parabola opening upward with vertex at the origin.", "img": "images/physics/ch1_q14.png"}, {"subject": "Physics", "chapter": "Basic Mathematics used in Physics", "q": "If the volume of a sphere increases at constant rate (dV/dt = 4). If radius of the sphere is denoted by r, then surface area of the sphere increases at the rate :-", "opts": ["4/r", "8/r", "12/r", "16/r"], "ans": 1, "mark": "Imp", "exp": "dV/dt = 4πr²(dr/dt) = 4, so dr/dt = 1/(πr²). dA/dt = 8πr(dr/dt) = 8/r."}, {"subject": "Physics", "chapter": "Basic Mathematics used in Physics", "q": "The position of a particle moving along x-axis varies with time t according as x = √3 sinωt − cosωt where ω is a constant. Find the region in which the particle is confined.", "opts": ["−2 ≤ x ≤ 2", "−3 ≤ x ≤ 3", "−√2 ≤ x ≤ √2", "−1 ≤ x ≤ 1"], "ans": 0, "mark": "Imp", "exp": "Amplitude = √((√3)² + 1²) = 2, so x lies between −2 and 2."}, {"subject": "Physics", "chapter": "Basic Mathematics used in Physics", "q": "For a spherical balloon, the rate of change of radius with respect to time is 2/π cm/s Find the rate of change of volume, when radius is 1/2 cm.", "opts": ["1 cm³/s", "2 cm³/s", "3 cm³/s", "4 cm³/s"], "ans": 1, "mark": "Imp", "exp": "dV/dt = 4πr²(dr/dt) = 4π × (1/4) × (2/π) = 2 cm³/s."}, {"subject": "Physics", "chapter": "Basic Mathematics used in Physics", "q": "Given that y = sin3x + (4/3)cos3x. What is the maximum rate of change in y with respect to x ?", "opts": ["7", "4", "5", "6"], "ans": 2, "mark": "Imp", "exp": "dy/dx = 3cos3x − 4sin3x, whose maximum value is √(3² + 4²) = 5."}, {"subject": "Physics", "chapter": "Basic Mathematics used in Physics", "q": "Given that y = 10/(sinx + √3 cosx). Minimum value of y is", "opts": ["zero", "2", "5", "10/(1+√3)"], "ans": 2, "mark": "Imp", "exp": "sinx + √3cosx = 2 sin(x+60°), max 2. So minimum (positive) y = 10/2 = 5."}, {"subject": "Physics", "chapter": "Basic Mathematics used in Physics", "q": "Find the rate of change of radius of a sphere when its radius is 4 cm and when its volume is changing at the rate of 4π/625 m³/sec.", "opts": ["1 m/s", "2 m/s", "π m/s", "3 m/s"], "ans": 0, "mark": "Imp", "exp": "dV/dt = 4πr²(dr/dt) with r = 0.04 m: dr/dt = (4π/625)/(4π × 0.0016) = 1 m/s."}, {"subject": "Physics", "chapter": "Basic Mathematics used in Physics", "q": "xy = c², then dy/dx equals :", "opts": ["x/y", "y/x", "−x/y", "−y/x"], "ans": 3, "mark": "Imp", "exp": "y = c²/x, so dy/dx = −c²/x² = −y/x."}, {"subject": "Physics", "chapter": "Basic Mathematics used in Physics", "q": "A metal rod extends on the x-axis from x = 0 m to x = 4 m. Its linear density ρ (mass/length) is not uniform and varies with the distance x from the origin according to equation ρ = (1.5 + 2x) kg/m. What is the mass of rod :-", "opts": ["16 kg", "22 kg", "28 kg", "32 kg"], "ans": 1, "mark": "Imp", "exp": "m = ∫₀⁴(1.5 + 2x)dx = 6 + 16 = 22 kg."}, {"subject": "Physics", "chapter": "Basic Mathematics used in Physics", "q": "The following curve represents a function y = f(x). Find average value of y when x changes from 0 to 6.", "opts": ["20/3", "25/3", "35/3", "40/3"], "ans": 1, "mark": "Imp", "exp": "Area under curve = 40 + 20 − 5 − 5 = 50. Average = 50/6 = 25/3.", "img": "images/physics/ch1_q23.png"}, {"subject": "Physics", "chapter": "Basic Mathematics used in Physics", "q": "Electric current in a wire is time rate of flow of charge. The charge in coulombs that passes through a wire after t seconds is given by the function q(t) = t³ − 2t² + 5t + 2. Determine the average current (in coulomb per second) during the first two seconds.", "opts": ["4A", "5A", "6A", "12A"], "ans": 1, "mark": "Imp", "exp": "q(2) = 12, q(0) = 2, so average current = (12 − 2)/2 = 5 A."}, {"subject": "Physics", "chapter": "Basic Mathematics used in Physics", "q": "Find ∫ from n−1 to n of (3 + 4t) dt :-", "opts": ["4n + 1", "4n + 5", "2n² + 1", "4n² + 5"], "ans": 0, "mark": "Imp", "exp": "∫(3+4t)dt = 3 + 2[n² − (n−1)²] = 3 + 2(2n − 1) = 4n + 1."}, {"subject": "Physics", "chapter": "Basic Mathematics used in Physics", "q": "Given that acceleration due to gravity (g) varies inversely as the square of the distance from the centre of the earth. Find its value at a height of 1600 km from the earth surface. The value of 'g' at the surface is 10 ms⁻². Radius of the earth = 6400 km.", "opts": ["6.4 ms⁻²", "5 ms⁻²", "10 ms⁻²", "7.2 ms⁻²"], "ans": 0, "mark": "Imp", "exp": "g' = 10 × (6400/8000)² = 10 × 0.64 = 6.4 ms⁻²."}, {"subject": "Physics", "chapter": "Basic Mathematics used in Physics", "q": "A body falls from a height of h = 3m. What is the total distance (in meters) it travels before it stops, if the body falls from a height h, strikes the ground and rebounds to a height e²h, falls down e²h and then rebounds back to a height e⁴h and so on. The coefficient of restitution between body and ground is e = 1/√3.", "opts": ["8 m", "6 m", "9 m", "12 m"], "ans": 1, "mark": "Imp", "exp": "Total = h + 2h(e² + e⁴ + ...) = h[1 + 2e²/(1−e²)] = 3(1 + 1) = 6 m (e² = 1/3)."}];
window.PRACTICE_SHEET_DATA["allen_vectors"] = [{"subject": "Physics", "chapter": "Vectors", "q": "A vector may change if -", "opts": ["frame of reference is translated", "vector is rotated", "frame of reference is rotated", "vector is translated parallel to itself"], "ans": 1, "mark": "Imp", "exp": "Rotating a vector changes its direction, so the vector changes. Translating the frame or the vector leaves it unchanged."}, {"subject": "Physics", "chapter": "Vectors", "q": "Let A⃗ = (1/√2)cosθ î + (1/√2)sinθ ĵ be any vector. What will be the unit vector n̂ in the direction of A⃗ ?", "opts": ["cosθ î + sinθ ĵ", "−cosθ î − sinθ ĵ", "(1/√2)(cosθ î + sinθ ĵ)", "(1/√2)(cosθ î − sinθ ĵ)"], "ans": 0, "mark": "Imp", "exp": "Unit vector = A⃗/|A⃗|; |A⃗| = 1/√2, so n̂ = cosθ î + sinθ ĵ."}, {"subject": "Physics", "chapter": "Vectors", "q": "Which of the following statement(s) is correct?", "opts": ["The unit vector of velocity and force may be same.", "The angle between two unit vectors is always 90°.", "The unit vector of velocity is always perpendicular to acceleration.", "The difference between magnitudes of two unit vector is equal to magnitude of difference of two unit vectors."], "ans": 0, "mark": "Imp", "exp": "Velocity and force can point in the same direction (e.g., free fall), so their unit vectors can be the same."}, {"subject": "Physics", "chapter": "Vectors", "q": "Two forces act on a particle simultaneously as shown in the figure. Find net force in milli newton on the particle. [Dyne is the CGS unit of force]", "opts": ["√3", "√2", "1", "2"], "ans": 2, "mark": "Imp", "exp": "100 dyne = 1 mN. The 100 dyne force is directed towards the particle, so the angle between the two forces is 120°: R = √(1 + 1 + 2cos120°) = 1 mN.", "img": "images/physics/ch2_q4.png"}, {"subject": "Physics", "chapter": "Vectors", "q": "The ratio of maximum and minimum magnitudes of the resultant of two vector a⃗ and b⃗ is 3 : 1. Now |a⃗| is equal to :", "opts": ["|b⃗|", "2|b⃗|", "3|b⃗|", "4|b⃗|"], "ans": 1, "mark": "Imp", "exp": "(a+b)/(a−b) = 3 → a + b = 3a − 3b → a = 2b."}, {"subject": "Physics", "chapter": "Vectors", "q": "Consider three vector A⃗, B⃗ and C⃗ as shown in figure. Choose the incorrect statement ?", "opts": ["A⃗ + B⃗ can be in the direction ↑", "A⃗ + B⃗ + C⃗ can be in the direction ↖", "A⃗ − B⃗ can be in the direction →", "A⃗ + B⃗ − C⃗ can be in the direction ↓"], "ans": 3, "mark": "Imp", "exp": "A⃗ + B⃗ points up and −C⃗ points right, so A⃗ + B⃗ − C⃗ is up-right and cannot be downward.", "img": "images/physics/ch2_q6.png"}, {"subject": "Physics", "chapter": "Vectors", "q": "For figure the correct relation is :-", "opts": ["A⃗ + B⃗ + E⃗ = 0⃗", "C⃗ − D⃗ = A⃗", "B⃗ + E⃗ − C⃗ = D⃗", "all of the above"], "ans": 0, "mark": "Imp", "exp": "Taking vectors around the closed path of the figure, A⃗ + B⃗ + E⃗ = 0⃗.", "img": "images/physics/ch2_q7.png"}, {"subject": "Physics", "chapter": "Vectors", "q": "Vector R⃗ is the resultant of the vectors A⃗ and B⃗. Ratio of minimum value of |R⃗| and maximum value of |R⃗| is 1/4. Then |A⃗|/|B⃗| may be:-", "opts": ["4/1", "2/1", "3/5", "1/4"], "ans": 2, "mark": "Imp", "exp": "(A−B)/(A+B) = 1/4 gives A/B = 5/3 (or 3/5 if B is larger)."}, {"subject": "Physics", "chapter": "Vectors", "q": "A particle is given successive displacements. Which of the following sets of displacements could be capable of returning the particle to its initial position?", "opts": ["10 m, 8m, 6 m, 30 m", "20 m, 10 m, 6m, 50 m", "65m, 15 m, 45 m, 30 m", "100 m, 18m, 22 m, 32 m"], "ans": 2, "mark": "Imp", "exp": "Largest displacement must be ≤ sum of the others: 65 ≤ 15 + 45 + 30 = 90."}, {"subject": "Physics", "chapter": "Vectors", "q": "Refer the following arrangements consisting of two vectors of same magnitude. Arrange them in ascending order of resultant magnitudes.", "opts": ["I, II, III, and IV", "IV, III, II and I", "II, IV, III and I", "II, I, III and IV"], "ans": 0, "mark": "Imp", "exp": "Angles between the vectors are 120°, 90°, 60°, 30° in I to IV. Resultant 2A cos(θ/2) increases as θ decreases, so I < II < III < IV.", "img": "images/physics/ch2_q10.png"}, {"subject": "Physics", "chapter": "Vectors", "q": "Three forces F1, F2 and F3 are represented as shown. Each of them is of equal magnitude. List-I (Combination): (P) F1+F2+F3, (Q) F1−F2+F3, (R) F1−F2−F3, (S) F2−F1−F3. List-II (Approximate Direction): (1) ↖ (2) ↘ (3) ↙ (4) ↗. Code :", "opts": ["P-1, Q-2, R-3, S-4", "P-2, Q-1, R-4, S-3", "P-2, Q-3, R-1, S-4", "P-4, Q-1, R-2, S-3"], "ans": 2, "mark": "Imp", "exp": "With F1 = (−0.7, 0.7), F2 = (1, 0), F3 = (0, −1): P = (0.3, −0.3) ↘ (2); Q = (−1.7, −0.3) ↙ (3); R = (−1.7, 1.7) ↖ (1); S = (1.7, 0.3) ↗ (4).", "img": "images/physics/ch2_q11.png"}, {"subject": "Physics", "chapter": "Vectors", "q": "The initial and final velocities of an object are as shown in figure (a). Which arrows shown in figure (b) can represent change in velocity vector.", "opts": ["A", "B", "C", "D"], "ans": 0, "mark": "Imp", "exp": "Δv⃗ = v⃗f − v⃗i points downward (slightly left), which matches arrow A.", "img": "images/physics/ch2_q12.png"}, {"subject": "Physics", "chapter": "Vectors", "q": "Two vectors A⃗ & B⃗ have magnitudes 2 & 1 respectively. If the angle between A⃗ & B⃗ is 60°, which of the following vectors may be equal to A⃗/2 − B⃗.", "opts": ["Arrow (1)", "Arrow (2)", "Arrow (3)", "Arrow (4)"], "ans": 1, "mark": "Imp", "exp": "A⃗/2 has magnitude 1 at 60° from B⃗; A⃗/2 − B⃗ has magnitude 1 and points up-left (120° from B⃗).", "img": "images/physics/ch2_q13.png"}, {"subject": "Physics", "chapter": "Vectors", "q": "A particle moves on a circular path of radius R. Find magnitude of its displacement during an interval in which it covers angular displacement θ.", "opts": ["Rθ", "R sinθ", "2R cos(θ/2)", "2R sin(θ/2)"], "ans": 3, "mark": "Imp", "exp": "Chord length = 2R sin(θ/2)."}, {"subject": "Physics", "chapter": "Vectors", "q": "Newton approximated motion in a circle as a series of linear motions, as in the polygon below. If we assume the particle moves at constant speed vA from A to B, and at constant speed vB from B to C, the direction of the change in velocity, Δv⃗, at point B, is shown by arrow:-", "opts": ["Arrow (1)", "Arrow (2)", "Arrow (3)", "Arrow (4)"], "ans": 1, "mark": "Imp", "exp": "Δv⃗ at a vertex points toward the centre of the polygon, i.e. down-left at B.", "img": "images/physics/ch2_q15.png"}, {"subject": "Physics", "chapter": "Vectors", "q": "The position vectors of two balls are given by r1 = 2(m) î + 7(m) ĵ and r2 = −2(m) î + 4(m) ĵ. What will be the distance between the two balls?", "opts": ["7 m", "5 m", "4 m", "3 m"], "ans": 1, "mark": "Imp", "exp": "r1 − r2 = 4î + 3ĵ; magnitude = 5 m."}, {"subject": "Physics", "chapter": "Vectors", "q": "If a⃗ = 2î + √5 ĵ & b⃗ = 5î + √5 ĵ + 4k̂, then find a vector of same magnitude as a⃗ and parallel to vector a⃗ − b⃗ :-", "opts": ["(7î + 2√5 ĵ + 4k̂)/3", "−3î − 4k̂", "(−9î − 12k̂)/5", "9î + 12k̂"], "ans": 2, "mark": "Imp", "exp": "a⃗ − b⃗ = −3î − 4k̂ (magnitude 5); |a⃗| = 3, so required vector = (3/5)(−3î − 4k̂)."}, {"subject": "Physics", "chapter": "Vectors", "q": "Two forces are simultaneously applied on an object. What third force would make the net force to point downwards?", "opts": ["Force (1)", "Force (2)", "Force (3)", "Force (4)"], "ans": 1, "mark": "Imp", "exp": "Existing net = F î + F ĵ. Option (2): 2F at 30° from y-axis gives −F î − √3F ĵ, so net = (1−√3)F ĵ, downward.", "img": "images/physics/ch2_q18.png"}, {"subject": "Physics", "chapter": "Vectors", "q": "Two vector a⃗ = 3î + 8ĵ − 2k̂ and b⃗ = 6î + 16ĵ + xk̂ are such that the component of b⃗ perpendicular to a⃗ is zero. Then the value of x will be :-", "opts": ["8", "−4", "+4", "−8"], "ans": 1, "mark": "Imp", "exp": "b⃗ must be parallel to a⃗: b⃗ = 2a⃗, so x = −4."}, {"subject": "Physics", "chapter": "Vectors", "q": "Two forces each of magnitude 5N is applied on block. One force is acting towards East and the other acting along 74° North of East. The resultant of the two forces is of magnitude :-", "opts": ["6 N", "10 N", "8 N", "12 N"], "ans": 2, "mark": "Imp", "exp": "R = 2 × 5 cos37° = 10 × 0.8 = 8 N."}, {"subject": "Physics", "chapter": "Vectors", "q": "Position of a particle at t = 0 is (2, 3, 0). It starts moving with a speed of 10 m/s in direction 37° north of west. Its position after t = 1 sec is (Take North as positive y-axis and East as positive x-axis) :-", "opts": ["(6, 11)", "(−4, 11)", "(−8, 6)", "(−6, 9)"], "ans": 3, "mark": "Imp", "exp": "Velocity = (−10cos37°, 10sin37°) = (−8, 6); position = (2 − 8, 3 + 6) = (−6, 9)."}, {"subject": "Physics", "chapter": "Vectors", "q": "Two forces (shown in figure) act on a body simultaneously. Among the given options which force when added will give resultant in North-East direction ?", "opts": ["1 N in North direction", "1 N in East direction", "3 N in West direction", "1 N in North-East direction"], "ans": 1, "mark": "Imp", "exp": "Existing forces: 4 N North, 3 N East. Adding 1 N East gives 4 N East and 4 N North, i.e. North-East.", "img": "images/physics/ch2_q22.png"}, {"subject": "Physics", "chapter": "Vectors", "q": "For the given vector A⃗ = 3î − 4ĵ + 10k̂, the ratio of magnitude of its component on the x-y plane and the component on z–axis is", "opts": ["2", "1/2", "1", "None of these"], "ans": 1, "mark": "Imp", "exp": "xy component = √(9+16) = 5; z component = 10; ratio = 1/2."}, {"subject": "Physics", "chapter": "Vectors", "q": "If A⃗ vector makes angle 90° & 30° with the x and y axis respectively then angle it makes with the z axis can be :", "opts": ["120°", "30°", "45°", "90°"], "ans": 0, "mark": "Imp", "exp": "cos²α + cos²β + cos²γ = 1 gives cos²γ = 1/4, so γ = 60° or 120°."}, {"subject": "Physics", "chapter": "Vectors", "q": "What is the length of projection of A⃗ = 3î + 4ĵ + 5k̂ on xy plane?", "opts": ["5", "3", "5√2", "4"], "ans": 0, "mark": "Imp", "exp": "Projection on xy plane = 3î + 4ĵ, length = 5."}, {"subject": "Physics", "chapter": "Vectors", "q": "A vector A⃗ is rotated through an angle π/2, the magnitude of new vector is -", "opts": ["2A", "A", "A/2", "Zero"], "ans": 1, "mark": "Imp", "exp": "Rotation does not change magnitude."}, {"subject": "Physics", "chapter": "Vectors", "q": "If a vector A⃗ makes angles α, β and γ respectively with the X, Y and Z axes respectively then sin²α + sin²β + sin²γ =", "opts": ["0", "1", "2", "3"], "ans": 2, "mark": "Imp", "exp": "cos²α + cos²β + cos²γ = 1, so the sin² sum = 3 − 1 = 2."}, {"subject": "Physics", "chapter": "Vectors", "q": "Three concurrent forces of the same magnitude are in equilibrium. What is the angle between the forces and the name of triangle formed by the forces as sides :-", "opts": ["60°, 60°, 60° & an equilateral triangle", "120°, 120°, 120° & an equilateral triangle", "120°, 30°, 30° & an isosceles triangle", "90°, 60°, 30° & a right angled triangle"], "ans": 1, "mark": "Imp", "exp": "Three equal forces in equilibrium are 120° apart and form an equilateral triangle."}, {"subject": "Physics", "chapter": "Vectors", "q": "θx and θy are the angles made by a vector A⃗ with positive x and positive y-axis respectively. Which set of θx and θy is not possible?", "opts": ["60°, 60°", "45°, 60°", "30°, 45°", "30°, 65°"], "ans": 2, "mark": "Imp", "exp": "cos²θx + cos²θy ≤ 1. For 30° and 45°: 3/4 + 1/2 > 1, not possible."}, {"subject": "Physics", "chapter": "Vectors", "q": "Refer the given figure and identify incorrect statement", "opts": ["Distance of A from x-axis is 5√3 cm.", "Distance of B from x-axis is 6 cm.", "Distance of A from y-axis is 5 cm.", "Distance of B from y-axis is 6 cm."], "ans": 3, "mark": "Imp", "exp": "B is at 143° from +x: distance from x-axis = 10 sin37° = 6 cm, from y-axis = 10 cos37° = 8 cm (not 6).", "img": "images/physics/ch2_q30.png"}, {"subject": "Physics", "chapter": "Vectors", "q": "a⃗ = 5 units due South-West, b⃗ = 5 units due 53° North of East, c⃗ = 10 units due 37° South of East. Then which of the following is incorrect :", "opts": ["a⃗ + b⃗ = −2î − ĵ", "a⃗·b⃗ = −35/√2", "b⃗·c⃗ = 0", "b⃗ + c⃗ = 11î − 2ĵ"], "ans": 0, "mark": "Imp", "exp": "b⃗ = 3î + 4ĵ and a⃗ = −(5/√2)(î + ĵ), so a⃗ + b⃗ ≠ −2î − ĵ; statement (1) is incorrect."}, {"subject": "Physics", "chapter": "Vectors", "q": "The angle between two vectors R⃗ = −î + (1/3)ĵ + k̂ and S⃗ = xî + 3ĵ + (x − 1)k̂", "opts": ["Is obtuse angle", "Is acute angle", "Is right angle", "Depends on x"], "ans": 2, "mark": "Imp", "exp": "R⃗·S⃗ = −x + 1 + (x − 1) = 0, so the angle is 90°."}, {"subject": "Physics", "chapter": "Vectors", "q": "If the angle between â & b̂ is 60°, then which of the following vector(s) have magnitude one :- (A) (â + b̂)/√3 (B) â − b̂ (C) â (D) b̂", "opts": ["Only C,D", "Only B,C,D", "Only A,C,D", "All"], "ans": 3, "mark": "Imp", "exp": "|â + b̂| = √3 and |â − b̂| = 1 at 60°, so all four have magnitude 1."}, {"subject": "Physics", "chapter": "Vectors", "q": "The dot product of two vectors of magnitudes 3 units and 5 units cannot be", "opts": ["2", "−2", "20", "zero"], "ans": 2, "mark": "Imp", "exp": "|a⃗·b⃗| ≤ 3 × 5 = 15, so 20 is impossible."}, {"subject": "Physics", "chapter": "Vectors", "q": "If a⃗ and b⃗ are two unit vectors such that a⃗ + 2b⃗ and 5a⃗ − 4b⃗ are perpendicular to each other then the angle between a⃗ and b⃗ is", "opts": ["45°", "60°", "cos⁻¹(1/3)", "cos⁻¹(2/7)"], "ans": 1, "mark": "Imp", "exp": "(a⃗+2b⃗)·(5a⃗−4b⃗) = 5 + 6cosθ − 8 = 0 → cosθ = 1/2 → θ = 60°."}, {"subject": "Physics", "chapter": "Vectors", "q": "If A⃗, B⃗ and C⃗ are vectors having a unit magnitude. If A⃗ + B⃗ + C⃗ = 0⃗ then A⃗·B⃗ + B⃗·C⃗ + C⃗·A⃗ will be :-", "opts": ["1", "−3/2", "−1/2", "zero"], "ans": 1, "mark": "Imp", "exp": "Squaring the sum: 3 + 2(A·B + B·C + C·A) = 0, so the sum = −3/2."}, {"subject": "Physics", "chapter": "Vectors", "q": "If A⃗ = 2î + ĵ + k̂ and B⃗ = î + 2ĵ + 2k̂, find the magnitude of component of (A⃗ + B⃗) along B⃗ :", "opts": ["4 unit", "5 unit", "6 unit", "7 unit"], "ans": 1, "mark": "Imp", "exp": "A⃗ + B⃗ = 3î + 3ĵ + 3k̂; component along B⃗ = (A⃗+B⃗)·B̂ = (3 + 6 + 6)/3 = 5."}, {"subject": "Physics", "chapter": "Vectors", "q": "The adjacent sides of a parallelogram are represented by co-initial vectors 2î + 3ĵ and î + 4ĵ. The area of the parallelogram is-", "opts": ["5 units along z-axis", "5 units in x-y plane", "3 units in x-z plane", "3 units in y-z plane"], "ans": 0, "mark": "Imp", "exp": "(2î+3ĵ)×(î+4ĵ) = (8 − 3)k̂ = 5k̂: magnitude 5 along the z-axis."}, {"subject": "Physics", "chapter": "Vectors", "q": "For a right handed coordinate system, positive x-axis is towards right of you and positive z-axis is upward then positive y-axis will be :", "opts": ["In front of you", "At back of you", "Towards left", "Downwards"], "ans": 0, "mark": "Imp", "exp": "x̂ × ŷ = ẑ: with x to the right and z up, y points away from you, i.e. in front."}, {"subject": "Physics", "chapter": "Vectors", "q": "If a = 2, b = 5 and |a⃗ × b⃗| = 8 then a⃗·b⃗ is", "opts": ["6", "12", "9", "4"], "ans": 0, "mark": "Imp", "exp": "10 sinθ = 8 → sinθ = 0.8, cosθ = 0.6, so a⃗·b⃗ = 10 × 0.6 = 6."}, {"subject": "Physics", "chapter": "Vectors", "q": "The sum of magnitudes of two forces acting at a point is 16N. If their resultant is normal to the smaller force and has a magnitude of 8N. Then the forces are-", "opts": ["6N, 10N", "8N, 8N", "4N, 12N", "2N, 14N"], "ans": 0, "mark": "Imp", "exp": "With P small and Q large: Q² − P² = 64 and Q + P = 16, so Q − P = 4 → Q = 10 N, P = 6 N."}];
